  top: -100%;
  left: 1rem;
  z-index: 100;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* ── Main / card ─────────────────────────────────────────────────── */
main {
  width: 100%;
  max-width: 540px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  margin-bottom: 1.5rem;
}

/* ── Form ────────────────────────────────────────────────────────── */
form {
  background: var(--bg-card);
  border: 1px solid var(--bg-card-border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

/* ── form-field wrapper ──────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* ── Fieldset / legend ───────────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-legend);
  padding: 0;
  margin-bottom: 0.25rem;
  float: left; /* keeps legend in flow on all browsers */
  width: 100%;
}

legend + * {
  clear: both;
}

.required-marker {
  color: var(--error);
  margin-left: 0.15em;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-top: -0.5rem;
}

/* ── Radio options ───────────────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--bg-card-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color var(--transition), border-color var(--transition);
  position: relative;
  font-size: 0.9375rem;
  color: var(--text-primary);
  user-select: none;
}

.radio-label:hover {
  background-color: var(--bg-hover);
  border-color: var(--accent);
