/* Hide the native radio visually but keep it accessible */
.radio-label input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

/* Custom radio circle */
.radio-custom {
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 50%;
  border: 2px solid var(--text-secondary);
  background: transparent;
  display: grid;
  place-items: center;
  transition: border-color var(--transition), background-color var(--transition);
}

.radio-custom::after {
  content: "";
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--accent);
  opacity: 0;
  transform: scale(0.5);
  transition: opacity var(--transition), transform var(--transition);
}

/* Checked state */
.radio-label input[type="radio"]:checked ~ .radio-custom {
  border-color: var(--accent);
  background: transparent;
}

.radio-label input[type="radio"]:checked ~ .radio-custom::after {
  opacity: 1;
  transform: scale(1);
}

.radio-label:has(input[type="radio"]:checked) {
  background-color: var(--bg-selected);
  border-color: var(--accent);
}

/* Keyboard focus visible on the label row */
.radio-label:has(input[type="radio"]:focus-visible) {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-color: var(--accent);
}

/* ── Error state ─────────────────────────────────────────────────── */
.error-message {
  font-size: 0.875rem;
  color: var(--error);
  background: var(--error-bg);
  border: 1px solid var(--error-border);
  border-radius: var(--radius-sm);
  padding: 0.5rem 0.75rem;
  margin-top: 0.25rem;
}

.error-message[hidden] {
  display: none;
}

fieldset.invalid .radio-label {
  border-color: var(--error-border);
}

/* ── Submit button ───────────────────────────────────────────────── */
button[type="submit"] {
  align-self: flex-start;
  background: var(--accent);
  color: #fff;
  font-size: 0.9375rem;
  font-weight: 600;
  padding: 0.75rem 1.75rem;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color var(--transition), box-shadow var(--transition);
}

button[type="submit"]:hover {
  background: var(--accent-hover);
}

button[type="submit"]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px var(--accent-ring);
}

/* ── Status message ──────────────────────────────────────────────── */
.status-message {
  margin-top: 1rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  min-height: 0;
}

.status-message:empty {
  display: none;
}

.status-message.success {
  background: #0d2b20;
  border: 1px solid #2a5c42;
  color: var(--success);
}

/* ── Forced Colors (Windows High Contrast) ───────────────────────── */
@media (forced-colors: active) {
  .radio-custom {
    forced-color-adjust: none;
    border-color: ButtonText;
    background: ButtonFace;
  }

  .radio-label input[type="radio"]:checked ~ .radio-custom {
    border-color: Highlight;
    background: ButtonFace;
  }

  .radio-custom::after {
    background: Highlight;
  }

  button[type="submit"] {
    forced-color-adjust: none;
    background: ButtonText;
    color: ButtonFace;
  }
}

/* ── Reduced motion ──────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0ms !important;
  }
}

/* ── Reflow / narrow viewports ───────────────────────────────────── */
@media (max-width: 400px) {
  form {
    padding: 1.25rem;
  }

  button[type="submit"] {
    width: 100%;
    text-align: center;
  }
}
