*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page:        #0f1117;
  --bg-card:        #1a1d27;
  --bg-card-border: #2e3148;
  --bg-hover:       #252840;
  --bg-selected:    #1e2a4a;

  --accent:         #6c8fff;
  --accent-hover:   #8da6ff;
  --accent-ring:    #6c8fff80;

  --text-primary:   #e8eaf6;
  --text-secondary: #9fa8c7;
  --text-legend:    #cbd2f0;

  --error:          #ff6b6b;
  --error-bg:       #2a1a1a;
  --error-border:   #ff6b6b55;

  --success:        #4caf8a;

  --radius-sm:  6px;
  --radius-md: 12px;
  --radius-lg: 18px;

  --transition: 150ms ease;
}

html {
  font-size: 100%;
}

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 1.5rem;
}

/* ── Skip link ───────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 100;
  background: var(--accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* ── Main / card ─────────────────────────────────────────────────── */
main {
  width: 100%;
  max-width: 540px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.01em;
  margin-bottom: 1.5rem;
}

/* ── Form ────────────────────────────────────────────────────────── */
form {
  background: var(--bg-card);
  border: 1px solid var(--bg-card-border);
  border-radius: var(--radius-lg);
  padding: 2rem;
  display: flex;
  flex-direction: column;
  gap: 1.75rem;
}

/* ── form-field wrapper ──────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0;
}

/* ── Fieldset / legend ───────────────────────────────────────────── */
fieldset {
  border: none;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-legend);
  padding: 0;
  margin-bottom: 0.25rem;
  float: left; /* keeps legend in flow on all browsers */
  width: 100%;
}

legend + * {
  clear: both;
}

.required-marker {
  color: var(--error);
  margin-left: 0.15em;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-top: -0.5rem;
}

/* ── Radio options ───────────────────────────────────────────────── */
.radio-options {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--bg-card-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color var(--transition), border-color var(--transition);
  position: relative;
  font-size: 0.9375rem;
  color: var(--text-primary);
  user-select: none;
}

.radio-label:hover {
  background-color: var(--bg-hover);
  border-color: var(--accent);
}

/* Hide the native radio visually but keep it accessible */
.radio-label input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
  pointer-events: none;
}

/* Custom radio circle */
.radio-custom {
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 50%;
  border: 2px solid var(--text-secondary);
  background: transparent;
  display: grid;
  place-items: center;
  transition: border-color var(--transition), background-color var(--transition);
}

.radio-custom::after {
  content: "";
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 50%;
  background: var(--accent);
  opacity: 0;
  transform: scale(0.5);
  transition: opacity var(--transition), transform var(--transition);
}

/* Checked state */
.radio-label input[type="radio"]:checked ~ .radio-custom {
  border-color: var(--accent);
  background: transparent;
}

.radio-label input[type="radio"]:checked ~ .radio-custom::after {
  opacity: 1;
  transform: scale(1);
}

.radio-label:has(input[type="radio"]:checked) {
  background-color: var(--bg-selected);
  border-color: var(--accent);
}

/* Keyboard focus visible on the label row */
.radio-label:has(input[type="radio"]:focus-visible) {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-color: var(--accent);
}

/* ── Error state ─────────────────────────────────────────────────── */
.error-message {
  font-size: 0.875rem;
  color: var(--error);
  background: var(--error-bg);
  border: 1px solid var(--error-border);
  border-radius: var(--radius-sm);
  padding: 0.5rem 0.75rem;
  margin-top: 0.25rem;
}

.error-message[hidden] {
  display: none;
}

fieldset.invalid .radio-label {
  border-color: var(--error-border);
}

/* ── Submit button ───────────────────────────────────────────────── */
button[type="submit"] {
  align-self: flex-start;
  background: var(--accent);
  color: #fff;
  font-size: 0.9375rem;
  font-weight: 600;
  padding: 0.75rem 1.75rem;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background-color var(--transition), box-shadow var(--transition);
}

button[type="submit"]:hover {
  background: var(--accent-hover);
}

button[type="submit"]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px var(--accent-ring);
}

/* ── Status message ──────────────────────────────────────────────── */
.status-message {
  margin-top: 1rem;
  padding: 0.75rem 1rem;
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  min-height: 0;
}

.status-message:empty {
  display: none;
}

.status-message.success {
  background: #0d2b20;
  border: 1px solid #2a5c42;
  color: var(--success);
}

/* ── Forced Colors (Windows High Contrast) ───────────────────────── */
@media (forced-colors: active) {
  .radio-custom {
    forced-color-adjust: none;
    border-color: ButtonText;
    background: ButtonFace;
  }

  .radio-label input[type="radio"]:checked ~ .radio-custom {
    border-color: Highlight;
    background: ButtonFace;
  }

  .radio-custom::after {
    background: Highlight;
  }

  button[type="submit"] {
    forced-color-adjust: none;
    background: ButtonText;
    color: ButtonFace;
  }
}

/* ── Reduced motion ──────────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0ms !important;
  }
}

/* ── Reflow / narrow viewports ───────────────────────────────────── */
@media (max-width: 400px) {
  form {
    padding: 1.25rem;
  }

  button[type="submit"] {
    width: 100%;
    text-align: center;
  }
}
