 (function () {
   'use strict';

   const form = document.getElementById('preferences-form');
   const fieldset = form.querySelector('fieldset');
   const errorMsg = document.getElementById('notif-error');
   const statusMsg = document.getElementById('status-message');

   form.addEventListener('submit', function (event) {
     event.preventDefault();

     const selected = form.querySelector('input[name="notification"]:checked');

     if (!selected) {
       // Show inline error
       errorMsg.hidden = false;
       fieldset.classList.add('invalid');
       // Move focus to first radio so the user can act immediately
       form.querySelector('input[name="notification"]').focus();
       // Clear any previous success
       statusMsg.textContent = '';
       statusMsg.className = 'status-message';
       return;
     }

     // Valid — clear error state
     errorMsg.hidden = true;
     fieldset.classList.remove('invalid');

     const labels = {
       email: 'Email',
       sms: 'SMS',
       push: 'Push Notifications',
     };

     statusMsg.textContent =
       'Preferences saved! You will receive notifications via ' +
       labels[selected.value] + '.';
     statusMsg.className = 'status-message success';
   });

   // Clear error as soon as user makes a selection
   fieldset.addEventListener('change', function () {
     errorMsg.hidden = true;
     fieldset.classList.remove('invalid');
   });
 })();

